import { cn } from '@/lib/utils';
import { format, parse } from 'date-fns';
import { ar } from 'date-fns/locale';
import { useCallback, useEffect, useMemo, useState } from 'react';
import { toast } from 'sonner';
import { PrimaryButton } from '@/components/buttons/PrimaryButton';
import { SecondaryButton } from '@/components/buttons/SecondaryButton';
import { endpoints } from '@/lib/axios/axios-global';
import { apiGet } from '@/lib/axios/axios-utils';
import { useResolvedEmployeeId } from '@/hooks/useResolvedEmployeeId';

type TodayRow = {
    check_in?: string | null;
    check_out?: string | null;
    status?: string | null;
};

function coerceTimeString(v: unknown): string | null {
    if (v == null || v === '') return null;
    if (typeof v === 'string') {
        if (v.includes('T')) {
            const t = v.split('T')[1];
            return t ? t.slice(0, 8) : null;
        }
        return v.length >= 8 ? v.slice(0, 8) : v;
    }
    return null;
}

function parseLocalDateTime(dateYmd: string, timeHms: string): Date | null {
    try {
        return parse(`${dateYmd} ${timeHms}`, 'yyyy-MM-dd HH:mm:ss', new Date());
    } catch {
        return null;
    }
}

function formatHms(totalSeconds: number): string {
    const s = Math.max(0, Math.floor(totalSeconds));
    const h = Math.floor(s / 3600);
    const m = Math.floor((s % 3600) / 60);
    const sec = s % 60;
    return [h, m, sec].map((n) => String(n).padStart(2, '0')).join(':');
}

function formatDisplayTime(time: string | null): string {
    if (!time) return '—';
    const d = parse(`2000-01-01 ${time}`, 'yyyy-MM-dd HH:mm:ss', new Date());
    if (Number.isNaN(d.getTime())) return time;
    return format(d, 'h:mm a', { locale: ar });
}

function workedHoursLabel(checkIn: string | null, checkOut: string | null, dateYmd: string): string {
    if (!checkIn || !checkOut) return '—';
    const a = parseLocalDateTime(dateYmd, checkIn);
    const b = parseLocalDateTime(dateYmd, checkOut);
    if (!a || !b || b <= a) return '—';
    const mins = Math.round((b.getTime() - a.getTime()) / 60000);
    const h = Math.floor(mins / 60);
    const m = mins % 60;
    return `${h} س ${m} د`;
}

export default function EntryExitSummaryCard({ className }: { className?: string }) {
    const employeeId = useResolvedEmployeeId();
    const [tick, setTick] = useState(() => Date.now());
    const [loading, setLoading] = useState(false);
    const [actionLoading, setActionLoading] = useState(false);
    const [todayRow, setTodayRow] = useState<TodayRow | null>(null);

    const dateYmd = format(new Date(), 'yyyy-MM-dd');
    const dayName = format(new Date(), 'EEEE', { locale: ar });
    const fullDate = format(new Date(), 'MMM d, yyyy', { locale: ar });

    const checkIn = coerceTimeString(todayRow?.check_in);
    const checkOut = coerceTimeString(todayRow?.check_out);

    const fetchToday = useCallback(async () => {
        if (employeeId == null) return;
        setLoading(true);
        try {
            const res = await apiGet({
                endpoint: endpoints.employeeAttendance.show + employeeId,
                queryParams: { date: dateYmd },
            });
            const rows = res.data?.data;
            const arr = Array.isArray(rows) ? rows : [];
            setTodayRow((arr[0] as TodayRow) ?? null);
        } catch {
            setTodayRow(null);
            toast.error('تعذر تحميل بيانات الحضور لهذا اليوم');
        } finally {
            setLoading(false);
        }
    }, [employeeId, dateYmd]);

    useEffect(() => {
        void fetchToday();
    }, [fetchToday]);

    useEffect(() => {
        if (!checkIn || checkOut) return;
        const id = window.setInterval(() => setTick(Date.now()), 1000);
        return () => window.clearInterval(id);
    }, [checkIn, checkOut]);

    const elapsedSinceCheckIn = useMemo(() => {
        if (!checkIn || checkOut) return 0;
        const start = parseLocalDateTime(dateYmd, checkIn);
        if (!start) return 0;
        return Math.max(0, Math.floor((tick - start.getTime()) / 1000));
    }, [checkIn, checkOut, dateYmd, tick]);

    const totalWorkedSeconds = useMemo(() => {
        if (!checkIn || !checkOut) return 0;
        const a = parseLocalDateTime(dateYmd, checkIn);
        const b = parseLocalDateTime(dateYmd, checkOut);
        if (!a || !b || b <= a) return 0;
        return Math.floor((b.getTime() - a.getTime()) / 1000);
    }, [checkIn, checkOut, dateYmd]);

    const onCheckIn = async () => {
        if (employeeId == null) return;
        setActionLoading(true);
        try {
            const res = await apiGet({ endpoint: endpoints.employeeAttendance.checkIn + employeeId });
            setTodayRow((res.data?.data as TodayRow) ?? todayRow);
            toast.success('تم تسجيل الدخول');
            await fetchToday();
        } catch (e: unknown) {
            const msg =
                (e as { response?: { data?: { msg?: string } } })?.response?.data?.msg ??
                'تعذر تسجيل الدخول (ربما تم التسجيل مسبقاً)';
            toast.error(msg);
        } finally {
            setActionLoading(false);
        }
    };

    const onCheckOut = async () => {
        if (employeeId == null) return;
        setActionLoading(true);
        try {
            const res = await apiGet({ endpoint: endpoints.employeeAttendance.checkOut + employeeId });
            setTodayRow((res.data?.data as TodayRow) ?? todayRow);
            toast.success('تم تسجيل الخروج');
            await fetchToday();
        } catch (e: unknown) {
            const msg =
                (e as { response?: { data?: { msg?: string } } })?.response?.data?.msg ??
                'تعذر تسجيل الخروج';
            toast.error(msg);
        } finally {
            setActionLoading(false);
        }
    };

    const canStart = Boolean(employeeId) && !checkIn;
    const canEnd = Boolean(employeeId) && Boolean(checkIn) && !checkOut;

    return (
        <section
            className={cn(
                'mb-4 rounded-lg bg-primery-blue-500 p-4 text-white-blue-50 shadow-[0px_4px_12px_0px_#0C0C0D1A]',
                className,
            )}
        >
            <div className="mb-4 text-center">
                <p className="text-base font-semibold leading-6">{dayName}</p>
                <p className="text-xs text-primery-blue-100">{fullDate}</p>
            </div>

            {employeeId == null ? (
                <p className="text-center text-sm text-primery-blue-100">تعذر تحديد الموظف المرتبط بحسابك.</p>
            ) : (
                <>
                    <div className="mb-3 flex flex-wrap justify-center gap-2">
                        <PrimaryButton
                            type="button"
                            disabled={!canStart || actionLoading || loading}
                            onClick={() => void onCheckIn()}
                            className="min-w-[120px] bg-white text-primery-blue-600 hover:bg-primery-blue-50"
                        >
                            بدء (تسجيل دخول)
                        </PrimaryButton>
                        <SecondaryButton
                            type="button"
                            disabled={!canEnd || actionLoading || loading}
                            onClick={() => void onCheckOut()}
                            className="min-w-[120px] border-white/60 text-white hover:bg-white/10"
                        >
                            إنهاء (تسجيل خروج)
                        </SecondaryButton>
                    </div>

                    <div className="mb-3 grid grid-cols-1 gap-3 md:grid-cols-2">
                        <div className="rounded-md border border-primery-blue-400 bg-primery-blue-600 px-4 py-3 text-center">
                            <p className="mb-1 text-xs text-primery-blue-100">وقت البدء (منذ تسجيل الدخول)</p>
                            <p className="text-2xl font-semibold leading-8 tabular-nums">
                                {!checkIn
                                    ? '00:00:00'
                                    : !checkOut
                                      ? formatHms(elapsedSinceCheckIn)
                                      : formatHms(totalWorkedSeconds)}
                            </p>
                        </div>
                        <div className="rounded-md border border-primery-blue-400 bg-primery-blue-600 px-4 py-3 text-center">
                            <p className="mb-1 text-xs text-primery-blue-100">وقت الانتهاء (مدة العمل اليوم)</p>
                            <p className="text-2xl font-semibold leading-8 tabular-nums">
                                {checkOut ? formatHms(totalWorkedSeconds) : '00:00:00'}
                            </p>
                        </div>
                    </div>

                    <div className="grid grid-cols-3 rounded-md border border-primery-blue-400 bg-primery-blue-600 px-2 py-3 text-center">
                        <div className="border-s border-primery-blue-400 px-2">
                            <p className="mb-1 text-xs text-primery-blue-100">الدخول</p>
                            <p className="text-sm">{loading ? '…' : formatDisplayTime(checkIn)}</p>
                        </div>
                        <div className="border-s border-primery-blue-400 px-2">
                            <p className="mb-1 text-xs text-primery-blue-100">الخروج</p>
                            <p className="text-sm">{loading ? '…' : formatDisplayTime(checkOut)}</p>
                        </div>
                        <div className="px-2">
                            <p className="mb-1 text-xs text-primery-blue-100">ساعات العمل</p>
                            <p className="text-sm">{loading ? '…' : workedHoursLabel(checkIn, checkOut, dateYmd)}</p>
                        </div>
                    </div>
                </>
            )}
        </section>
    );
}
